import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const transactionTypes = new Set([
  "buy_vwce", "sell_vwce", "buy_security", "sell_security",
  "cash_in", "cash_out", "tax", "fee", "safe_interest", "adjust",
]);

type RecordRow = { id: string; data: Record<string, unknown> | null; deleted_at: string | null };
const jsonHeaders = { "Content-Type": "application/json", "Cache-Control": "no-store" };

function reply(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), { status, headers: jsonHeaders });
}
function plainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}
function dateIsValid(value: unknown): boolean {
  if (typeof value !== "string" || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value)) return false;
  const timestamp = Date.parse(value + "T00:00:00Z");
  return Number.isFinite(timestamp) && new Date(timestamp).toISOString().slice(0, 10) === value;
}
function finite(value: unknown): boolean {
  return typeof value === "number" && Number.isFinite(value);
}

Deno.serve(async (req: Request) => {
  if (req.method !== "GET") return reply({ ok: false, error: "GET required" }, 405);
  const baseUrl = Deno.env.get("SUPABASE_URL");
  const anon = Deno.env.get("SUPABASE_ANON_KEY");
  const auth = req.headers.get("Authorization") ?? "";
  if (!baseUrl || !anon) return reply({ ok: false, error: "Server configuration unavailable" }, 503);
  if (!/^Bearer[ ]+[^ ]+$/i.test(auth)) return reply({ ok: false, error: "Sign-in required" }, 401);
  try {
    const identityResponse = await fetch(baseUrl + "/auth/v1/user", {
      headers: { Authorization: auth, apikey: anon },
      signal: AbortSignal.timeout(8000),
    });
    if (!identityResponse.ok) return reply({ ok: false, error: "Sign-in required" }, 401);
    const identity = await identityResponse.json();
    const userId = identity?.id;
    if (typeof userId !== "string" || !/^[a-f0-9-]{36}$/i.test(userId)) {
      return reply({ ok: false, error: "Sign-in required" }, 401);
    }

    async function load(domain: string): Promise<RecordRow[]> {
      const search = new URLSearchParams({
        select: "id,data,deleted_at",
        user_id: "eq." + userId,
        limit: "1001",
      });
      const response = await fetch(baseUrl + "/rest/v1/" + domain + "?" + search.toString(), {
        headers: { Authorization: auth, apikey: anon, Accept: "application/json" },
        signal: AbortSignal.timeout(10000),
      });
      if (!response.ok) throw new Error("Database read blocked: " + domain + ":" + response.status);
      const rows = await response.json();
      if (!Array.isArray(rows)) throw new Error("Unexpected database response");
      return rows;
    }

    const domains = ["transactions", "goals", "app_settings"];
    const datasets = await Promise.all(domains.map(load));
    const checks: Record<string, unknown> = {};
    let errors = 0;
    let incomplete = false;
    for (let j = 0; j < domains.length; j++) {
      const domain = domains[j];
      const rows = datasets[j];
      if (rows.length >= 1000) incomplete = true;
      const active = rows.filter((r) => r.deleted_at === null);
      let mismatchedIds = 0;
      let invalidAmount = 0;
      let invalidType = 0;
      let invalidDate = 0;
      for (const row of active) {
        if (!plainObject(row.data) || row.id !== row.data.id) mismatchedIds++;
        if (!plainObject(row.data)) continue;
        if (domain !== "app_settings" && !finite(row.data.amount)) invalidAmount++;
        if (domain === "transactions") {
          if (!transactionTypes.has(String(row.data.type))) invalidType++;
          if (!dateIsValid(row.data.date)) invalidDate++;
        }
      }
      const issues = { mismatchedIds, invalidAmount, invalidType, invalidDate };
      errors += Object.values(issues).reduce((a, b) => a + b, 0);
      checks[domain] = { active: active.length, tombstones: rows.length - active.length, issues };
    }

    return reply({
      ok: true,
      mode: "read_only",
      notificationsEnabled: false,
      status: incomplete ? "incomplete" : errors > 0 ? "review" : "pass_basic_checks",
      checkedAt: new Date().toISOString(),
      checks,
      limitations: [
        "Server-side rows only; local Dexie and pending outbox are not visible",
        "Basic structural checks only; not a financial or sync completeness audit",
        ...(incomplete ? ["Over 1000 rows in at least one domain; results are incomplete"] : []),
      ],
    });
  } catch (error) {
    console.error("Guardian read-only check failed", error instanceof Error ? error.message : "unknown");
    return reply({ ok: false, error: "Read-only check unavailable" }, 503);
  }
});

